package hotel;

import static readcode.Assert.*;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;

public class AvailabilityTest {
    private InMemoryRoomInventory inventory;
    private AvailabilityService service;
    private final LocalDate night = LocalDate.of(2026, 12, 24);

    public void setUp() {
        inventory = new InMemoryRoomInventory();
        inventory.add(new Room("101", "double", 120));
        inventory.add(new Room("102", "double", 95));
        inventory.add(new Room("201", "suite", 260));
        inventory.add(new Room("103", "single", 70));
        service = new AvailabilityService(inventory);
    }

    public void testSearchFiltersAndSortsByRate() {
        List<Room> found = service.search("double", 200, night);
        assertEquals(2, found.size());
        assertEquals("102", found.get(0).number());
        assertEquals("101", found.get(1).number());
    }

    public void testSearchDoesNotShrinkInventory() {
        service.search("suite", 300, night);
        assertEquals(4, inventory.size(), "inventory lost rooms after a search");
    }

    public void testRepeatedSearchGivesSameResult() {
        List<Room> first = service.search("double", 200, night);
        List<Room> second = service.search("double", 200, night);
        assertEquals(first, second, "second identical search returned different rooms");
        assertEquals(2, second.size());
    }

    public void testSearchForOtherTypeStillFindsRooms() {
        service.search("single", 100, night);
        List<Room> suites = service.search("suite", 300, night);
        assertEquals(1, suites.size(), "a previous search for another type hid the suite");
    }

    public void testBookedRoomOnlyUnavailableForThatNight() {
        Optional<Room> booked = service.bookCheapest("double", 200, night);
        assertEquals("102", booked.get().number());
        assertEquals(1, service.search("double", 200, night).size());
        List<Room> nextNight = service.search("double", 200, night.plusDays(1));
        assertEquals(2, nextNight.size(), "room booked for one night vanished from other nights");
    }

    public void testOccupancyUsesFullInventory() {
        service.bookCheapest("double", 200, night);
        service.bookCheapest("single", 200, night);
        double occupancy = service.occupancy(night);
        System.out.println("occupancy on " + night + " = " + occupancy + " with " + inventory.size() + " rooms");
        assertEquals(0.5, occupancy, 0.0001);
    }

    public void testCallerCannotChangeInventoryThroughRooms() {
        List<Room> view = inventory.rooms();
        view.clear();
        assertEquals(4, inventory.size(), "clearing the returned list emptied the inventory");
    }

    public void testRemoveByNumber() {
        assertTrue(inventory.remove("201"));
        assertFalse(inventory.remove("999"));
        assertEquals(3, inventory.size());
    }
}
